// Generated by Cypress Author on 2026-11-01.

type TestAccount = "user" | "incompleteUser" | "trainer" | "admin";

function requiredEnv(name: string): string {
  const value = Cypress.env(name);
  if (typeof value !== "string" || !value)
    throw new Error(`Missing Cypress environment value: ${name}`);
  return value;
}

function signInAs(account: TestAccount): void {
  const prefix = {
    user: "user",
    incompleteUser: "incompleteUser",
    trainer: "trainer",
    admin: "admin",
  }[account];
  cy.visit("/");
  cy.clerkSignIn({
    strategy: "password",
    identifier: requiredEnv(`${prefix}Email`),
    password: requiredEnv(`${prefix}Password`),
  });
  cy.visit("/");
}

function currentToken(): Cypress.Chainable<string> {
  return cy
    .window()
    .its("Clerk")
    .then((clerk) => clerk.session?.getToken())
    .then((token) => {
      expect(token, "Clerk session token").to.be.a("string");
      expect(token, "Clerk session token").to.not.equal("");
      return token!;
    });
}

function fillPlan(title: string): void {
  cy.contains("button", "New plan").click();
  cy.contains("label", "Plan title").find("input").clear().type(title);
  cy.contains("label", "Goal")
    .find("input")
    .clear()
    .type("Build sustainable strength");
  cy.contains("label", "Start date").find("input").type("2026-11-01");
  cy.contains("label", "End date").find("input").type("2026-12-01");
  cy.contains("label", "Day 1 name").find("input").clear().type("Strength");
  cy.contains("label", "Exercise name").find("input").clear().type("Squat");
}

function createPlanAsAssignedUser(
  title: string,
): Cypress.Chainable<{ id: string; workoutDayId: string }> {
  signInAs("user");
  cy.contains("a", "My Plans").click();
  cy.intercept("POST", "/api/training-plans").as("createPlan");
  fillPlan(title);
  cy.contains("button", "Create plan").click();
  return cy.wait("@createPlan").then(({ response }) => {
    expect(response?.statusCode).to.eq(201);
    const body = response?.body as {
      id: string;
      workoutDays: Array<{ id: string }>;
    };
    expect(body.workoutDays).to.have.length.greaterThan(0);
    return { id: body.id, workoutDayId: body.workoutDays[0].id };
  });
}

describe("FitPath critical user workflows", () => {
  it("visit protected application while signed out → shows public entry point", () => {
    cy.visit("/plans");
    cy.contains("h1", "FitPath").should("be.visible");
    cy.contains("a", "Sign in").should("be.visible");
    cy.contains("h2", "Plan editor").should("not.exist");
  });

  it("sign in as an onboarded user → reaches FitPath dashboard", () => {
    signInAs("user");
    cy.contains("h2", "Welcome to your FitPath dashboard").should("be.visible");
  });

  it("sign in with incomplete onboarding → is routed to onboarding", () => {
    signInAs("incompleteUser");
    cy.contains("h1", "Tell us about yourself").should("be.visible");
  });

  it("create a training plan → persists the structured plan", () => {
    const title = `Cypress user plan ${Date.now()}`;
    createPlanAsAssignedUser(title);
    cy.contains("[role=status]", "Training plan saved.").should("be.visible");
    cy.contains("button", title).should("be.visible");
  });

  it("record progress → creates an authenticated progress entry", () => {
    signInAs("user");
    currentToken()
      .then((token) =>
        cy.request({
          method: "POST",
          url: "/api/me/progress",
          headers: { Authorization: `Bearer ${token}` },
          body: { weightKg: 72.4, recordedAt: "2026-10-31T12:00:00.000Z" },
        }),
      )
      .then((response) => {
        expect(response.status).to.eq(201);
        expect(response.body.entry).to.include({ weightKg: 72.4 });
      });
  });

  it("mark a workout complete → records completion for the plan owner", () => {
    createPlanAsAssignedUser(`Cypress completion plan ${Date.now()}`).then(
      ({ workoutDayId }) => {
        cy.intercept("POST", `/api/workout-days/${workoutDayId}/complete`).as(
          "completeWorkout",
        );
        cy.contains("button", "Mark complete").click();
        cy.wait("@completeWorkout")
          .its("response.statusCode")
          .should("eq", 201);
        cy.contains("button", "Undo completion").should("be.visible");
      },
    );
  });

  it("download a training-plan PDF → receives an authorized PDF response", () => {
    createPlanAsAssignedUser(`Cypress PDF plan ${Date.now()}`).then(() => {
      cy.intercept("GET", "/api/training-plans/*/pdf").as("downloadPdf");
      cy.contains("button", "Download PDF").click();
      cy.wait("@downloadPdf").then(({ response }) => {
        expect(response?.statusCode).to.eq(200);
        expect(response?.headers["content-type"]).to.contain("application/pdf");
      });
    });
  });

  it("approve a pending trainer application as ADMIN → promotes the applicant", () => {
    signInAs("admin");
    currentToken()
      .then((token) =>
        cy.request({
          method: "PATCH",
          url: `/api/admin/trainer-applications/${requiredEnv("pendingTrainerApplicationId")}/approve`,
          headers: { Authorization: `Bearer ${token}` },
        }),
      )
      .then((response) => {
        expect(response.status).to.eq(200);
        expect(response.body).to.deep.equal({ status: "APPROVED" });
      });
  });

  it("open trainer workspace → sees assigned client", () => {
    signInAs("trainer");
    cy.contains("a", "My Clients").click();
    cy.contains("h2", "My Clients").should("be.visible");
    cy.contains(requiredEnv("assignedClientClerkUserId")).should("be.visible");
  });

  it("edit an assigned client plan as TRAINER → saves the change", () => {
    const title = `Cypress trainer plan ${Date.now()}`;
    createPlanAsAssignedUser(title).then(() => {
      signInAs("trainer");
      cy.contains("a", "My Plans").click();
      cy.contains("button", title).click();
      cy.intercept("PUT", "/api/training-plans/*").as("updatePlan");
      cy.contains("label", "Goal")
        .find("input")
        .clear()
        .type("Trainer-reviewed strength plan");
      cy.contains("button", "Save changes").click();
      cy.wait("@updatePlan").its("response.statusCode").should("eq", 200);
      cy.contains("[role=status]", "Training plan saved.").should("be.visible");
    });
  });

  it("request unrelated client data as TRAINER → is forbidden", () => {
    signInAs("trainer");
    currentToken()
      .then((token) =>
        cy.request({
          failOnStatusCode: false,
          url: `/api/training-plans/${requiredEnv("unrelatedPlanId")}`,
          headers: { Authorization: `Bearer ${token}` },
        }),
      )
      .then((response) => {
        expect(response.status).to.eq(403);
        expect(response.body).to.deep.equal({ error: "Forbidden" });
      });
  });
});
